INSERT INTO events (id,title,description,content,location,link,start_date,end_date,status,featured) SELECT '9764b745-05cb-411d-937e-b2ef879695c1','Data & AI in Finance Workshop','Budgeting, investing and how Data & AI are reshaping finance, with Ms. Bea Charmelyn Lambitco, FRM.','CSters came together for a session that brought financial concepts to life in the context of real challenges Filipinos face today: inflation, low savings rates and financial accessibility. It covered practical strategies for budgeting, investing and building long-term financial stability, and how Data & AI are reshaping finance, from fraud detection and alternative credit scoring to personalised financial systems. Thank you to Ms. Bea Charmelyn Lambitco, FRM, for sharing her expertise.','','https://www.facebook.com/share/p/1D597LfzE3/','2026-03-18','2026-03-18','done',0 WHERE NOT EXISTS (SELECT 1 FROM events WHERE title = 'Data & AI in Finance Workshop');
INSERT INTO events (id,title,description,content,location,link,start_date,end_date,status,featured) SELECT 'e6acf323-0f08-40eb-81db-01a1732adecb','ARCANA: Seal of Connection webinar','Partnership with SWITS on purpose-driven networking, with Koach Victor Libanan Jr. and Koach Brian Dys Sahagun.','CompSciety partnered with SWITS for ARCANA: Seal of Connection, the fifth webinar in their series, on the Networking Manual for purpose-driven connections. Koach Victor Libanan Jr. (Process Analyst Manager, JTI GBS Philippines) spoke on building a personal definition of mentorship. Koach Brian Dys Sahagun (Principal Designer, Avaloq) shared how he mentors designers in UX and product design.','Online','https://www.facebook.com/share/p/1e6w8uT5H7/','2026-03-27','2026-03-27','done',0 WHERE NOT EXISTS (SELECT 1 FROM events WHERE title = 'ARCANA: Seal of Connection webinar');
INSERT INTO events (id,title,description,content,location,link,start_date,end_date,status,featured) SELECT '952324ab-a01b-4768-85e2-98718b1f78d8','Data & AI in Finance Challenge','Data & AI: Budget. Invest. Build. Teams built financial web apps, and the top 6 went to a public vote.','The final stage of the Data & AI: Budget. Invest. Build. Challenge. After crunching numbers, debugging code and deploying their projects, the top 6 teams presented working financial web apps, and CSters voted for their favourite with heart reacts until April 4, 2026 (11:59 PM).','Online','https://www.facebook.com/share/p/1DjtWYP37x/','2026-04-02','2026-04-04','done',1 WHERE NOT EXISTS (SELECT 1 FROM events WHERE title = 'Data & AI in Finance Challenge');
INSERT INTO events (id,title,description,content,location,link,start_date,end_date,status,featured) SELECT '1215833f-1e35-447b-8b1a-918b0e03f84c','World Quantum Week in the Philippines 2026','A week of quantum computing competitions and talks with partners across the Philippines.','From April 14 to 19, CSters explored the quantum frontier through a competition, talks and sessions for World Quantum Week in the Philippines 2026. Thank you to all the partners, volunteers and participants who made the week memorable. To more quantum-ready Filipinos!','','https://www.facebook.com/share/p/1JFvRT8ybB/','2026-04-14','2026-04-19','done',1 WHERE NOT EXISTS (SELECT 1 FROM events WHERE title = 'World Quantum Week in the Philippines 2026');
